path='/root/weoapr2025all.xls'
with open(path,'r',encoding='utf-16') as f:
    header=f.readline().strip('\n')
    headers=header.split('\t')
    print('headers', headers[:10])
    cols={h:i for i,h in enumerate(headers)}
    # find Georgia rows for codes
    target_codes={'NGDP_R','NGDP_RPCH','NGDP_D'}
    rows={}
    for line in f:
        parts=line.rstrip('\n').split('\t')
        if len(parts)<len(headers):
            continue
        if parts[cols['Country']]=='Georgia' and parts[cols['WEO Subject Code']] in target_codes:
            code=parts[cols['WEO Subject Code']]
            rows[code]=parts
    print('found codes', rows.keys())
    for code, parts in rows.items():
        vals={year: parts[cols[str(year)]] for year in range(2020,2028)}
        print(code, parts[cols['Units']], parts[cols['Scale']], vals)
